    throw methodNotFound(`Unknown tool: ${name}`);
  }

  if (args == null || typeof args !== 'object' || Array.isArray(args)) {
    throw invalidParams('arguments must be an object');
  }

  const keys = Object.keys(args);
  if (keys.length !== 1 || keys[0] !== 'ids') {
    throw invalidParams('batch_lookup accepts only the "ids" argument');
  }

  const { ids } = args;

  if (!Array.isArray(ids)) {
    throw invalidParams('"ids" must be an array');
  }
  if (ids.length === 0) {
    throw invalidParams('"ids" must be a non-empty array');
  }
  for (const id of ids) {
    if (typeof id !== 'string') {
      throw invalidParams('every element of "ids" must be a string');
    }
